CREATE TABLE orphan_visits_counts (id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, potential_bot BOOLEAN DEFAULT false NOT NULL, count BIGINT DEFAULT 1 NOT NULL, slot_id INT NOT NULL, PRIMARY KEY (id));
CREATE UNIQUE INDEX UQ_slot ON orphan_visits_counts (potential_bot, slot_id);
CREATE TABLE short_urls (id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, original_url TEXT NOT NULL, long_url_hash BYTEA NOT NULL, short_code VARCHAR(255) NOT NULL, date_created TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, valid_since TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL, valid_until TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL, max_visits INT DEFAULT NULL, import_source VARCHAR(255) DEFAULT NULL, import_original_short_code VARCHAR(255) DEFAULT NULL, title VARCHAR(512) DEFAULT NULL, title_was_auto_resolved BOOLEAN DEFAULT false NOT NULL, crawlable BOOLEAN DEFAULT false NOT NULL, forward_query BOOLEAN DEFAULT true NOT NULL, domain_id BIGINT DEFAULT NULL, author_api_key_id BIGINT DEFAULT NULL, PRIMARY KEY (id));
CREATE INDEX IDX_long_url_hash ON short_urls (long_url_hash);
CREATE UNIQUE INDEX unique_short_code_plus_domain ON short_urls (short_code, domain_id);
CREATE INDEX IDX_4A53F934115F0EE5 ON short_urls (domain_id);
CREATE INDEX IDX_4A53F934C9EA6E08 ON short_urls (author_api_key_id);
CREATE TABLE short_urls_in_tags (short_url_id BIGINT NOT NULL, tag_id BIGINT NOT NULL, PRIMARY KEY (short_url_id, tag_id));
CREATE INDEX IDX_59775203F1252BC8 ON short_urls_in_tags (short_url_id);
CREATE INDEX IDX_59775203BAD26311 ON short_urls_in_tags (tag_id);
CREATE TABLE visits (id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, referer VARCHAR(1024) DEFAULT NULL, "date" TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, remote_addr VARCHAR(256) DEFAULT NULL, user_agent VARCHAR(512) DEFAULT NULL, visited_url VARCHAR(2048) DEFAULT NULL, type VARCHAR(255) NOT NULL, potential_bot BOOLEAN DEFAULT false NOT NULL, redirect_url VARCHAR(2048) DEFAULT NULL, short_url_id BIGINT DEFAULT NULL, visit_location_id BIGINT DEFAULT NULL, PRIMARY KEY (id));
CREATE INDEX IDX_visits_date ON visits (date);
CREATE INDEX IDX_444839EAF1252BC8 ON visits (short_url_id);
CREATE INDEX IDX_444839EA8297882E ON visits (visit_location_id);
CREATE TABLE short_url_redirect_rules (id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, priority INT NOT NULL, long_url TEXT NOT NULL, short_url_id BIGINT NOT NULL, PRIMARY KEY (id));
CREATE INDEX IDX_448348BCF1252BC8 ON short_url_redirect_rules (short_url_id);
CREATE TABLE redirect_conditions_in_short_url_redirect_rules (short_url_redirect_rule_id BIGINT NOT NULL, redirect_condition_id BIGINT NOT NULL, PRIMARY KEY (short_url_redirect_rule_id, redirect_condition_id));
CREATE INDEX IDX_62CF4FA4BE19B441 ON redirect_conditions_in_short_url_redirect_rules (short_url_redirect_rule_id);
CREATE INDEX IDX_62CF4FA49AE7732E ON redirect_conditions_in_short_url_redirect_rules (redirect_condition_id);
CREATE TABLE redirect_conditions (id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, type VARCHAR(255) NOT NULL, match_key VARCHAR(512) DEFAULT NULL, match_value VARCHAR(512) DEFAULT NULL, PRIMARY KEY (id));
CREATE TABLE tags (id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, name VARCHAR(255) NOT NULL, PRIMARY KEY (id));
CREATE UNIQUE INDEX UNIQ_6FBC94265E237E06 ON tags (name);
CREATE TABLE visit_locations (id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, country_code VARCHAR(255) DEFAULT NULL, country_name VARCHAR(255) DEFAULT NULL, region_name VARCHAR(255) DEFAULT NULL, city_name VARCHAR(255) DEFAULT NULL, timezone VARCHAR(255) DEFAULT NULL, lat DOUBLE PRECISION NOT NULL, lon DOUBLE PRECISION NOT NULL, is_empty BOOLEAN DEFAULT false NOT NULL, PRIMARY KEY (id));
CREATE TABLE domains (id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, authority VARCHAR(255) NOT NULL, base_url_redirect TEXT DEFAULT NULL, regular_not_found_redirect TEXT DEFAULT NULL, invalid_short_url_redirect TEXT DEFAULT NULL, PRIMARY KEY (id));
CREATE UNIQUE INDEX UNIQ_8C7BBF9D4AF96AFC ON domains (authority);
CREATE TABLE short_url_visits_counts (id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, potential_bot BOOLEAN DEFAULT false NOT NULL, count BIGINT DEFAULT 1 NOT NULL, slot_id INT NOT NULL, short_url_id BIGINT DEFAULT NULL, PRIMARY KEY (id));
CREATE UNIQUE INDEX UQ_slot_per_short_url ON short_url_visits_counts (short_url_id, potential_bot, slot_id);
CREATE INDEX IDX_28E514E3F1252BC8 ON short_url_visits_counts (short_url_id);
CREATE TABLE geolocation_db_updates (id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, date_created TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, date_updated TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL, status VARCHAR(128) NOT NULL, error VARCHAR(1024) DEFAULT NULL, reason VARCHAR(1024) NOT NULL, filesystem_id VARCHAR(512) NOT NULL, PRIMARY KEY (id));
CREATE INDEX IDX_geolocation_date_updated ON geolocation_db_updates (date_updated);
CREATE INDEX IDX_geolocation_status_filesystem ON geolocation_db_updates (filesystem_id);
CREATE TABLE api_keys (id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, "key" VARCHAR(255) NOT NULL, "name" VARCHAR(255) DEFAULT NULL, expiration_date TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL, enabled BOOLEAN NOT NULL, PRIMARY KEY (id));
CREATE UNIQUE INDEX UNIQ_9579321FF48571EB ON api_keys ("key");
CREATE TABLE api_key_roles (id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, role_name VARCHAR(255) NOT NULL, meta JSON NOT NULL, api_key_id BIGINT NOT NULL, PRIMARY KEY (id));
